import type { StoryBeat } from "@/lib/domain/story-world";
import type { RamayanaBeginningPlayableScene } from "./ramayana-beginnings-playable";

const beat = (
  id: string,
  title: { en: string; hi: string },
  narration: { en: string; hi: string },
  visualCue: string,
  characterIds: string[],
): StoryBeat => ({ id, title, narration, visualCue, characterIds });

const scene = (
  id: string,
  nodeIds: string[],
  decisiveChange: { en: string; hi: string },
  beats: StoryBeat[],
): RamayanaBeginningPlayableScene => ({ id, nodeIds, moment: { id, decisiveChange, beats } });

export const RAMAYANA_INDRAJIT_LAST_WAR_PLAYABLE_SCENES: RamayanaBeginningPlayableScene[] = [
  scene("atikaya-meets-lakshmana", ["atikaya", "lakshmana", "rama", "vibhishana", "allied-fighters", "lanka-defenders", "war-chariot", "golden-armour", "wind-counsel", "battlefield"], { en: "Lakshmana learns why ordinary weapons cannot pierce Atikaya and ends a contest that first appeared impossible.", hi: "लक्ष्मण जान लेते हैं कि सामान्य अस्त्र अतिकाय को क्यों नहीं भेदते और पहले असंभव लगते संघर्ष को समाप्त करते हैं।" }, [
    beat("atikaya-repeats-kumbhakarnas-fear", { en: "Atikaya repeats Kumbhakarna's fear", hi: "अतिकाय कुंभकर्ण वाला भय लौटा देता है" }, { en: "Atikaya enters on a radiant chariot after brothers and uncles have fallen. His height, equipment, and proclaimed name make allied fighters believe Kumbhakarna has returned, and they crowd toward Rama for protection. Fear grows from remembered danger and incomplete recognition before Atikaya has even chosen a direct opponent.", hi: "भाइयों और मामाओं के गिरने के बाद अतिकाय चमकते रथ पर आता है। उसका कद, साज-सामान और पुकारा नाम मित्र-योद्धाओं को कुंभकर्ण लौटने का भ्रम देते हैं और वे सुरक्षा के लिए राम की ओर सिमटते हैं। अतिकाय द्वारा सीधा विरोधी चुनने से पहले ही पुराना संकट और अधूरी पहचान भय बढ़ा देते हैं।" }, "Let Atikaya's silhouette briefly inherit Kumbhakarna's scale, then separate the two identities as Vibhishana's recognition reaches the ranks.", ["atikaya", "rama", "vibhishana", "allied-fighters"]),
    beat("vibhishana-identifies-more-than-a-target", { en: "Vibhishana identifies more than a target", hi: "विभीषण केवल लक्ष्य नहीं, पूरा परिचय बताते हैं" }, { en: "Vibhishana names Atikaya as Ravana's son, describes his learning, counsel, skill with several forms of combat, protection of Lanka, and the armour granted after austerity. The identification restores orientation without reducing him to a giant obstacle. Ability, service, and danger remain visible together as the allied leaders decide who can meet him.", hi: "विभीषण अतिकाय को रावण का पुत्र बताते हुए उसका ज्ञान, परामर्श, कई युद्ध-विधाओं का कौशल, लंका की रक्षा और तप के बाद मिला कवच बताते हैं। परिचय उसे विशाल बाधा तक सीमित किए बिना दिशा लौटाता है। मित्र-नेता उसका सामना तय करते समय क्षमता, सेवा और खतरे—तीनों को साथ देखते हैं।" }, "Replace the anonymous threat with connected skill, family, armour, and city-service nodes while keeping his approaching route clear.", ["vibhishana", "atikaya", "ravana", "lanka", "allied-fighters"]),
    beat("the-duel-keeps-cancelling-itself", { en: "The duel keeps cancelling itself", hi: "द्वंद्व बार-बार स्वयं को रोकता है" }, { en: "Lakshmana answers Atikaya's challenge after smaller groups cannot break through. Their arrows, fire, wind, water, and other empowered weapons meet and cancel in the air. Atikaya acknowledges a strong hit even while returning it. The exchange shows two skilled opponents adapting rather than a simple rise in visual force until someone wins.", hi: "छोटे दलों के रास्ता न बना पाने पर लक्ष्मण अतिकाय की चुनौती स्वीकार करते हैं। उनके बाण और अग्नि, वायु, जल तथा अन्य शक्तिशाली अस्त्र आकाश में मिलकर एक-दूसरे को रोकते हैं। अतिकाय एक सशक्त प्रहार को मानता भी है और उत्तर भी देता है। संघर्ष केवल दृश्य शक्ति बढ़ने के बजाय दो कुशल विरोधियों का अनुकूलन दिखाता है।" }, "Make each weapon interaction alter the available field and disappear on contact, avoiding an endlessly escalating pile of effects.", ["lakshmana", "atikaya", "war-chariot", "battlefield"]),
    beat("the-armour-changes-the-question", { en: "The armour changes the question", hi: "कवच प्रश्न बदल देता है" }, { en: "Lakshmana's arrows break against Atikaya's armour until the wind reveals that the protection, not lack of courage or skill, is deciding the exchange. Lakshmana then uses the one weapon described as capable of passing it and kills Atikaya. The surviving defenders retreat in grief; the ending is tactical discovery, not proof that Atikaya's whole life was worthless.", hi: "लक्ष्मण के बाण अतिकाय के कवच पर टूटते हैं, जब तक वायु नहीं बताती कि साहस या कौशल की कमी नहीं, सुरक्षा संघर्ष तय कर रही है। लक्ष्मण तब वही अस्त्र चलाते हैं जो उसे पार कर सकता है और अतिकाय मारा जाता है। बचे रक्षक शोक में लौटते हैं; अंत सैन्य खोज है, अतिकाय के पूरे जीवन को निरर्थक सिद्ध करना नहीं।" }, "Show failed arrows mapping the armour boundary, then one precise breach followed by grieving withdrawal rather than a celebratory gore close-up.", ["lakshmana", "atikaya", "wind-counsel", "golden-armour", "lanka-defenders"]),
  ]),
  scene("ravana-guards-what-remains", ["ravana", "indrajit", "sita", "atikaya", "lanka-guards", "palace", "ashoka-grove", "lanka-gates", "watch-routes", "allied-army"], { en: "Ravana finally treats the allied army as a sustained threat, but uses that recognition to tighten control rather than reverse the cause.", hi: "रावण अंततः मित्र-सेना को स्थायी खतरा मानता है, पर उस पहचान से कारण पलटने के बजाय नियंत्रण कसता है।" }, [
    beat("the-list-of-the-dead-becomes-real", { en: "The list of the dead becomes real", hi: "मृतकों की सूची वास्तविक हो उठती है" }, { en: "News of Atikaya makes Ravana name Dhumraksha, Akampana, Prahasta, Kumbhakarna, sons, brothers, and many other fighters already lost. Earlier confidence gives way to a count he can no longer dismiss. The list is not a set of defeated pieces; each name carries a command role, relationship, and absence now felt inside Lanka.", hi: "अतिकाय का समाचार रावण से धूम्राक्ष, अकंपन, प्रहस्त, कुंभकर्ण, पुत्रों, भाइयों और अनेक खोए योद्धाओं के नाम कहलवाता है। पिछला आत्मविश्वास ऐसी गिनती में बदलता है जिसे अब नकारा नहीं जा सकता। सूची हारे मोहरों की नहीं; हर नाम कमान, संबंध और लंका में महसूस होती अनुपस्थिति रखता है।" }, "Let each named loss remove a distinct relationship and defence route from Ravana's map instead of incrementing one casualty number.", ["ravana", "atikaya", "kumbhakarna", "lanka-commanders", "lanka"]),
    beat("recovery-breaks-his-explanation", { en: "Recovery breaks his explanation", hi: "स्वस्थ लौटना रावण की व्याख्या तोड़ देता है" }, { en: "Ravana cannot explain how Rama and Lakshmana escaped bonds he believed no celestial or powerful being could loosen. The recovery forces him to accept that his information and expectations are unreliable. He recognises the allied fighters as dangerous and explicitly warns that they must no longer be slighted, but insight still stops short of restitution.", hi: "रावण समझ नहीं पाता कि राम और लक्ष्मण उन बंधनों से कैसे छूटे जिन्हें वह देवताओं या शक्तिशाली प्राणियों के लिए भी अटूट मानता था। उनका उठना उसे अपनी जानकारी और अपेक्षा की अविश्वसनीयता स्वीकार करवाता है। वह मित्र-योद्धाओं को खतरनाक मानकर उन्हें कम न आँकने को कहता है, पर समझ अब भी वापसी तक नहीं पहुँचती।" }, "Break Ravana's certainty model with the brothers' recovery, then leave the return-Sita path visible but deliberately unused.", ["ravana", "rama", "lakshmana", "sita", "allied-army"]),
    beat("watches-close-around-sita", { en: "Watches close around Sita", hi: "सीता के चारों ओर पहरा कसता है" }, { en: "Ravana orders the palace, gates, approaches, and Ashoka grove watched at evening, midnight, and morning. Every entry and exit is to be recorded. The same military anxiety that protects the city also intensifies Sita's confinement, making a person he abducted into guarded territory inside a shrinking defensive system.", hi: "रावण महल, द्वार, रास्ते और अशोक-वाटिका पर संध्या, आधी रात और सुबह पहरा लगाने को कहता है। हर आने-जाने वाले की खबर रखनी है। नगर की रक्षा करने वाली सैन्य चिंता सीता की कैद भी कसती है और अपहृत व्यक्ति को सिमटती रक्षा-व्यवस्था के भीतर पहरे वाला क्षेत्र बना देती है।" }, "Tighten watch routes around military gates and Sita's grove together, while visually distinguishing protection of residents from control of a captive.", ["ravana", "sita", "lanka-guards", "ashoka-grove", "lanka-gates"]),
    beat("fear-settles-on-the-remaining-son", { en: "Fear settles on the remaining son", hi: "भय बचे हुए पुत्र पर टिक जाता है" }, { en: "After issuing orders, Ravana withdraws carrying anger and visible anxiety for Indrajit. His remaining defence has narrowed around one son's capacity for concealment and extraordinary weapons. The father's fear is genuine, but the dependence also places Indrajit under the demand to repair losses created by a decision Ravana still refuses to undo.", hi: "आदेश देकर रावण क्रोध और इंद्रजीत के लिए स्पष्ट चिंता के साथ भीतर लौटता है। बची रक्षा अब एक पुत्र की अदृश्यता और असाधारण अस्त्रों की क्षमता पर सिमट गई है। पिता का भय सच्चा है, पर यह निर्भरता इंद्रजीत पर उन हानियों को सुधारने का भार डालती है जिन्हें रावण अब भी अपना निर्णय पलटकर रोकना नहीं चाहता।" }, "Contract Lanka's defence network onto Indrajit while keeping the father-son bond and Ravana's unresolved causal choice both visible.", ["ravana", "indrajit", "lanka", "sita"]),
  ]),
  scene("indrajit-turns-invisible-again", ["indrajit", "ravana", "rama", "lakshmana", "hanuman", "sugriva", "jambavan", "allied-fighters", "martial-altar", "hidden-chariot", "battlefield"], { en: "Indrajit overwhelms the visible army again, and Rama uses endurance and apparent defeat to end an attack they cannot locate.", hi: "इंद्रजीत दृश्य सेना को फिर दबाता है और राम ऐसे आक्रमण को समाप्त करने के लिए सहनशीलता तथा दिखाई पड़ती हार का उपयोग करते हैं जिसका स्थान वे नहीं जानते।" }, [
    beat("a-son-promises-to-end-his-fathers-grief", { en: "A son promises to end his father's grief", hi: "पुत्र पिता का शोक समाप्त करने का वचन देता है" }, { en: "Indrajit sees Ravana grieving relatives and promises that his father will watch Rama and Lakshmana fall before the day ends. The vow gives the court movement, yet it also converts family sorrow into a demand for another son's decisive violence. Indrajit leaves carrying both personal confidence and the burden of restoring his father's world.", hi: "इंद्रजीत रावण को संबंधियों के लिए शोक करते देखकर वचन देता है कि दिन समाप्त होने से पहले पिता राम-लक्ष्मण को गिरता देखेंगे। वचन सभा को गति देता है, पर पारिवारिक शोक को दूसरे पुत्र की निर्णायक हिंसा की माँग में बदल देता है। इंद्रजीत अपना आत्मविश्वास और पिता का संसार लौटाने का भार—दोनों लेकर निकलता है।" }, "Move grief from Ravana into Indrajit's vow as a visible family pressure line, not merely a mission marker.", ["indrajit", "ravana", "lanka-court"]),
    beat("the-rite-prepares-a-military-advantage", { en: "The rite prepares a military advantage", hi: "अनुष्ठान सैन्य बढ़त तैयार करता है" }, { en: "Indrajit performs a formal fire offering with weapons, cloth, grain, and an animal before empowering his bow, vehicle, and concealment. Within this account the rite belongs to a specific wartime technology and lineage; it is not a template for present practice. Its practical result in the encounter is unequal visibility that the opposing army cannot reproduce.", hi: "इंद्रजीत शस्त्र, वस्त्र, अन्न और पशु के साथ औपचारिक अग्नि-अर्पण करके धनुष, वाहन और अदृश्यता को समर्थ बनाता है। इस वृत्तांत में अनुष्ठान विशेष युद्ध-विधि और वंश से जुड़ा है; यह आज की पूजा का नमूना नहीं। संघर्ष में उसका व्यावहारिक परिणाम असमान दृश्यता है जिसे विरोधी सेना दोहरा नहीं सकती।" }, "Stage the rite as bounded epic-era military preparation, clearly separated from present-day devotional or household practice.", ["indrajit", "martial-altar", "hidden-chariot", "lanka-defenders"]),
    beat("the-field-can-see-only-impacts", { en: "The field can see only impacts", hi: "मैदान केवल प्रहार देख पाता है" }, { en: "Indrajit wounds named leaders, scattered fighters, Rama, and Lakshmana from a position hidden even by sound. People look upward, shield one another, and fall without locating the route of danger. His tactical success is real, but invisibility should not become an essential quality assigned to every person from Lanka or every opponent described by his kinship.", hi: "इंद्रजीत ऐसे स्थान से नामित सेनानायकों, बिखरे योद्धाओं, राम और लक्ष्मण को घायल करता है जिसका संकेत ध्वनि भी नहीं देती। लोग ऊपर देखते, एक-दूसरे को ढकते और खतरे की राह जाने बिना गिरते हैं। उसकी सैन्य सफलता वास्तविक है, पर अदृश्यता को लंका के हर व्यक्ति या उसके संबंध से बताए हर विरोधी का जन्मजात गुण नहीं बनाना चाहिए।" }, "Reveal only wounds, arrow paths, and defensive reactions; keep the hidden origin specific to Indrajit's tactic rather than to an entire people.", ["indrajit", "rama", "lakshmana", "allied-fighters", "battlefield"]),
    beat("rama-chooses-to-bear-the-weapon", { en: "Rama chooses to bear the weapon", hi: "राम अस्त्र सहने का निर्णय लेते हैं" }, { en: "Rama recognises the empowered attack and tells Lakshmana to endure it calmly rather than answer with uncontrolled escalation. He predicts that Indrajit will leave after seeing the leaders and army apparently defeated. Both brothers go still by decision inside terrible injury, using the attacker's need to confirm success as the only available way to close the encounter.", hi: "राम समर्थ आक्रमण पहचानकर लक्ष्मण से अनियंत्रित बढ़त के बजाय उसे शांत रहकर सहने को कहते हैं। वे अनुमान लगाते हैं कि नेता और सेना को हारा देखकर इंद्रजीत लौट जाएगा। दोनों भाई गंभीर चोट के बीच निर्णय से निश्चल होते हैं और आक्रमणकारी की सफलता मानने की जरूरत को संघर्ष बंद करने की एकमात्र उपलब्ध राह बनाते हैं।" }, "Make stillness a costly tactical choice with faint coordination between the brothers, not a triumphant immunity or effortless trick.", ["rama", "lakshmana", "indrajit", "allied-fighters"]),
  ]),
  scene("hanuman-carries-the-mountain", ["hanuman", "jambavan", "vibhishana", "rama", "lakshmana", "sugriva", "sushena", "wounded-allies", "medicine-mountain", "himalaya", "lanka-fallen"], { en: "A search for survivors becomes a medicine journey that restores the reachable wounded while exposing unequal access to care.", hi: "जीवित लोगों की खोज औषधि-यात्रा बनती है जो पहुँच सकने वाले घायलों को उठाती और उपचार की असमान पहुँच खोलती है।" }, [
    beat("two-lights-search-the-field", { en: "Two lights search the field", hi: "दो रोशनियाँ मैदान खोजती हैं" }, { en: "Vibhishana and Hanuman carry fire across a field covered with injured and motionless bodies. They do not begin by celebrating survival of the central brothers; they look for anyone still living and identify leaders one by one. The wide devastation makes rescue a search problem in which missed people may lose the only remaining chance for care.", hi: "विभीषण और हनुमान घायल तथा निश्चल शरीरों से भरे मैदान में अग्नि लेकर चलते हैं। वे मुख्य भाइयों के बचने का उत्सव शुरू नहीं करते; वे हर जीवित व्यक्ति को खोजते और एक-एक नेता पहचानते हैं। व्यापक विनाश बचाव को ऐसी खोज बनाता है जिसमें छूटा व्यक्ति उपचार का अंतिम अवसर खो सकता है।" }, "Sweep two careful light cones across persistent bodies, marking confirmed breathing and aid needs without converting the field into gore spectacle.", ["vibhishana", "hanuman", "wounded-allies", "battlefield"]),
    beat("jambavan-recognises-a-voice", { en: "Jambavan recognises a voice", hi: "जाम्बवान आवाज़ पहचानते हैं" }, { en: "Jambavan is too wounded to see Vibhishana but recognises his voice and asks whether Hanuman lives. The question is not a ranking of whose life matters. He explains that Hanuman's reach can still connect every wounded person to a distant remedy, so one confirmed survivor changes the practical horizon for the whole field.", hi: "जाम्बवान इतने घायल हैं कि विभीषण को देख नहीं सकते, पर आवाज़ पहचानकर पूछते हैं कि हनुमान जीवित हैं या नहीं। प्रश्न यह नहीं तय करता कि किसका जीवन अधिक मूल्यवान है। वे बताते हैं कि हनुमान की पहुँच हर घायल को दूर की औषधि से जोड़ सकती है, इसलिए एक जीवित व्यक्ति की पुष्टि पूरे मैदान की व्यावहारिक संभावना बदल देती है।" }, "Connect Hanuman to many wounded nodes through a distant medicine route, explaining Jambavan's priority without dimming anyone else's worth.", ["jambavan", "vibhishana", "hanuman", "wounded-allies"]),
    beat("not-knowing-the-plant-does-not-end-the-mission", { en: "Not knowing the plant does not end the mission", hi: "पौधा न पहचान पाना अभियान समाप्त नहीं करता" }, { en: "Hanuman crosses to the mountain named by Jambavan but cannot distinguish the four medicines after they conceal themselves. Anger rises, and he uproots the summit rather than return empty-handed. The act damages trees, slopes, animals, and the mountain itself; determination solves the identification failure through scale, but its environmental cost remains visible.", hi: "हनुमान जाम्बवान द्वारा बताए पर्वत तक पहुँचते हैं, पर छिप जाने पर चार औषधियों को अलग नहीं पहचानते। क्रोध उठता है और वे खाली लौटने के बजाय शिखर उखाड़ लेते हैं। इससे वृक्ष, ढलान, पशु और पर्वत स्वयं घायल होते हैं; दृढ़ता बड़े उपाय से पहचान की विफलता सुलझाती है, पर पर्यावरणीय कीमत दृश्य रहती है।" }, "Lift the summit only after failed close inspection, carrying displaced trees, animals, and rock as consequences rather than weightless decoration.", ["hanuman", "medicine-mountain", "himalaya", "wounded-allies"]),
    beat("the-fragrance-reaches-only-those-present", { en: "The fragrance reaches only those present", hi: "सुगंध केवल उपस्थित लोगों तक पहुँचती है" }, { en: "The medicine fragrance restores Rama, Lakshmana, and the allied wounded gathered on the field. Lanka's forces had removed their dead into the sea to conceal losses, so their fallen do not receive the same benefit. The contrast is not evidence that one side deserved life more; location, recovery practice, and access determine who is reached by care.", hi: "औषधि की सुगंध राम, लक्ष्मण और मैदान में जुटे मित्र-पक्ष के घायलों को उठा देती है। लंका की सेना हानि छिपाने के लिए अपने मृतकों को समुद्र में हटा चुकी थी, इसलिए उसके गिरे लोगों को वही लाभ नहीं मिलता। अंतर यह सिद्ध नहीं करता कि एक पक्ष जीवन का अधिक अधिकारी था; स्थान, शव-संभाल की प्रथा और पहुँच तय करते हैं कि उपचार किस तक पहुँचा।" }, "Let restorative light spread by physical proximity and stop at absent bodies, explicitly mapping access rather than moral entitlement.", ["rama", "lakshmana", "allied-fighters", "lanka-fallen", "medicine-mountain"]),
  ]),
  scene("lanka-burns-around-its-families", ["sugriva", "rama", "lakshmana", "allied-fighters", "lanka-defenders", "lanka-families", "children", "burning-homes", "city-animals", "lanka-gates", "waterfront"], { en: "The allied assault burns military stores and family homes together, making civilian harm and coercion inside its own ranks impossible to hide.", hi: "मित्र-पक्ष का आक्रमण सैन्य भंडार और पारिवारिक घर साथ जलाता है, जिससे नागरिक हानि और अपने दल पर दबाव छिप नहीं सकता।" }, [
    beat("fire-crosses-the-gates", { en: "Fire crosses the gates", hi: "अग्नि द्वार पार करती है" }, { en: "After the recovery, Sugriva sends fast fighters carrying firebrands through and around Lanka's gates at night. Guards flee and the attack reaches roads, upper rooms, armour stores, vehicles, weapons, and other military resources. It also immediately enters a lived city where no clean line separates a command depot from the next household.", hi: "स्वस्थ होने के बाद सुग्रीव रात में अग्नि लिए तेज योद्धाओं को लंका के द्वारों से भीतर और आसपास भेजते हैं। रक्षक भागते हैं और आक्रमण सड़कों, ऊपरी कक्षों, कवच-भंडार, वाहनों, शस्त्रों तथा सैन्य साधनों तक पहुँचता है। वह तुरंत ऐसे जीवित नगर में भी प्रवेश करता है जहाँ कमान-भंडार और अगले घर के बीच साफ सीमा नहीं।" }, "Trace fire from gate defences into mixed military and residential blocks, refusing to colour every burning structure as a valid target.", ["sugriva", "allied-fighters", "lanka-defenders", "burning-homes", "lanka-gates"]),
    beat("families-wake-inside-the-assault", { en: "Families wake inside the assault", hi: "परिवार आक्रमण के भीतर जागते हैं" }, { en: "Sleeping people wake to smoke, women abandon ornaments, adults run carrying children, and frightened horses and elephants trigger one another. Cries travel far beyond the immediate clash. These residents cannot be folded into the word enemy merely because their homes stand inside Ravana's capital; the assault has consequences for people who did not choose his refusal.", hi: "सोते लोग धुएँ में जागते, स्त्रियाँ आभूषण छोड़तीं, बड़े बच्चों को उठाकर भागते और डरे घोड़े तथा हाथी एक-दूसरे का भय बढ़ाते हैं। पुकारें तत्काल संघर्ष से बहुत दूर जाती हैं। ये निवासी केवल रावण की राजधानी में घर होने से शत्रु नहीं बन जाते; आक्रमण उन लोगों को भी चोट देता है जिन्होंने उसका इनकार नहीं चुना।" }, "Prioritise evacuation paths, carried children, and panicked animals through smoke; keep military combat markers separate from residents.", ["lanka-families", "children", "city-animals", "burning-homes"]),
    beat("combat-meets-people-leaving-buildings", { en: "Combat meets people leaving buildings", hi: "भवनों से निकलते लोगों के बीच युद्ध आ जाता है" }, { en: "Some armed defenders emerge from burning structures and are attacked by waiting allied fighters. The same street may therefore contain a combatant, an injured resident, an escaping family, and a loose animal. A readable path must preserve those distinctions; rapid engagement cannot assume everyone coming through smoke presents the same threat.", hi: "कुछ सशस्त्र रक्षक जलते भवनों से निकलते और प्रतीक्षारत मित्र-योद्धाओं से लड़ते हैं। इसलिए एक ही सड़क पर योद्धा, घायल निवासी, भागता परिवार और खुला पशु साथ हो सकते हैं। समझने योग्य राह को ये अंतर बचाने होंगे; धुएँ से निकलने वाला हर व्यक्ति समान खतरा मानकर तेज युद्ध नहीं चल सकता।" }, "Use uncertain smoke reveals that require identification before attack, with protected civilian exits crossing but not merging into combat lanes.", ["allied-fighters", "lanka-defenders", "lanka-families", "city-animals"]),
    beat("sugriva-threatens-his-own-ranks", { en: "Sugriva threatens his own ranks", hi: "सुग्रीव अपने ही दल को धमकाते हैं" }, { en: "Sugriva orders fighters to hold assigned gates and says anyone leaving a rank should be killed by force. The command may aim to prevent collapse during a dangerous assault, but it makes allied survival conditional on obedience and closes legitimate retreat. It belongs in the moral cost of the operation, not beneath a simple image of unified courage.", hi: "सुग्रीव योद्धाओं को तय द्वार थामने और पंक्ति छोड़ने वाले को बल से मारने का आदेश देते हैं। आदेश खतरनाक आक्रमण में टूटन रोकना चाहता हो सकता है, पर वह साथी का जीवन आज्ञापालन पर निर्भर करता और वैध पीछे हटना बंद करता है। यह अभियान की नैतिक कीमत का हिस्सा है, एकजुट साहस की सरल छवि के नीचे छिपने वाली बात नहीं।" }, "Visibly mark coercive blocking of allied retreat routes and keep it distinct from voluntary formation, discipline, and mutual protection.", ["sugriva", "allied-fighters", "lanka-gates", "retreat-routes"]),
  ]),
  scene("kumbhakarnas-sons-enter-the-fire", ["kumbha", "nikumbha", "angada", "mainda", "dwivida", "sugriva", "hanuman", "kampana", "sonitaksha", "yupaksha", "prajangha", "burning-battlefield", "sea"], { en: "Kumbhakarna's sons and relatives enter a fight already shaped by fire and family loss, and each death drives the next encounter.", hi: "कुंभकर्ण के पुत्र और संबंधी अग्नि तथा पारिवारिक हानि से बने युद्ध में उतरते हैं और हर मृत्यु अगला संघर्ष चलाती है।" }, [
    beat("relatives-arrive-as-a-connected-unit", { en: "Relatives arrive as a connected unit", hi: "संबंधी जुड़े दल की तरह आते हैं" }, { en: "Ravana sends Kumbha, Nikumbha, Kampana, Sonitaksha, Yupaksha, and Prajangha into the illuminated night after fire has spread through Lanka. They are not isolated replacements. Brothers, uncle, nephew, and companions enter with bonds that affect whom they protect, whose fall they see, and why anger moves quickly from one encounter to another.", hi: "लंका में अग्नि फैलने के बाद रावण कुंभ, निकुंभ, कंपन, शोणिताक्ष, यूपाक्ष और प्रजंघ को उजली रात में भेजता है। वे अलग-अलग बदली मोहरे नहीं हैं। भाई, मामा, भतीजे और साथी ऐसे संबंध लेकर आते हैं जो तय करते हैं कि वे किसकी रक्षा करेंगे, किसे गिरता देखेंगे और क्रोध एक संघर्ष से दूसरे तक इतनी जल्दी क्यों जाएगा।" }, "Enter the formation as a family-and-command network whose links remain visible throughout the separate clashes.", ["kumbha", "nikumbha", "kampana", "sonitaksha", "yupaksha", "prajangha"]),
    beat("angadas-circle-keeps-changing", { en: "Angada's circle keeps changing", hi: "अंगद का घेरा बदलता रहता है" }, { en: "Angada meets Kampana and Sonitaksha before Mainda and Dwivida help against a tightening group. Weapons change hands, people recover from blows, and one relative's death pulls another closer. The action is severe, but the important structure is mutual defence and cascading grief, not detailed attention to bodies being torn or crushed.", hi: "अंगद कंपन और शोणिताक्ष से भिड़ते हैं, फिर मैंद और द्विविद कसते घेरे के विरुद्ध साथ आते हैं। शस्त्र हाथ बदलते, लोग प्रहार से संभलते और एक संबंधी की मृत्यु दूसरे को निकट खींचती है। कार्रवाई कठोर है, पर मूल संरचना पारस्परिक रक्षा और फैलता शोक है, शरीर चीरने या कुचलने का विस्तृत तमाशा नहीं।" }, "Keep support links and grief-triggered target changes clearer than bodily injury, using distance and aftermath for severe outcomes.", ["angada", "mainda", "dwivida", "kampana", "sonitaksha", "yupaksha", "prajangha"]),
    beat("sugriva-and-kumbha-pause-before-impact", { en: "Sugriva and Kumbha pause before impact", hi: "सुग्रीव और कुंभ प्रहार से पहले ठहरते हैं" }, { en: "Kumbha disables Mainda, Dwivida, and Angada before Sugriva carries Angada away and confronts him. Sugriva openly praises Kumbha's strength and offers him recovery time, saying public censure would follow an attack on an exhausted opponent. Respect and reputation slow the exchange briefly without ending a war driven by their wider commitments.", hi: "कुंभ मैंद, द्विविद और अंगद को अक्षम करता है; तब सुग्रीव अंगद को हटाकर उसका सामना करते हैं। सुग्रीव कुंभ की शक्ति मानते और उसे विश्राम का समय देते हैं, क्योंकि थके विरोधी पर प्रहार से लोक-निंदा होगी। सम्मान और प्रतिष्ठा संघर्ष को क्षण भर धीमा करते हैं, पर व्यापक दायित्वों से चले युद्ध को समाप्त नहीं करते।" }, "Pause combat with visible exhaustion and Angada's rescue, then show praise as restraint without turning the opponents into friends outside the fight.", ["sugriva", "kumbha", "angada", "mainda", "dwivida"]),
    beat("two-brothers-fall-in-sequence", { en: "Two brothers fall in sequence", hi: "दो भाई क्रम से गिरते हैं" }, { en: "Sugriva and Kumbha wrestle through the water and return to land before Kumbha dies from a final blow. Nikumbha sees his brother fall, charges with a massive weapon, briefly captures Hanuman, and is killed in the ensuing struggle. The linked endings show grief accelerating exposure to danger; they are not two independent victories resetting the field.", hi: "सुग्रीव और कुंभ जल में संघर्ष करके भूमि पर लौटते हैं और अंतिम प्रहार से कुंभ मरता है। निकुंभ भाई को गिरते देखकर विशाल शस्त्र लेकर बढ़ता, कुछ समय हनुमान को पकड़ता और अगले संघर्ष में मारा जाता है। जुड़े अंत दिखाते हैं कि शोक खतरे में उतरना तेज करता है; वे मैदान को नया करने वाली दो अलग जीतें नहीं।" }, "Carry Kumbha's fall directly into Nikumbha's grief-driven route while preserving wounded allies and the burning city around both encounters.", ["sugriva", "kumbha", "nikumbha", "hanuman", "burning-battlefield", "sea"]),
  ]),
  scene("makaraksha-brings-kharas-grief", ["makaraksha", "khara", "ravana", "rama", "lakshmana", "allied-fighters", "lanka-defenders", "war-chariot", "dandaka-memory", "battlefield"], { en: "Makaraksha confronts Rama with an inherited wound from Dandaka, but grief becomes another fatal route rather than repair.", hi: "मकराक्ष दंडक की विरासत वाली चोट लेकर राम का सामना करता है, पर शोक सुधार के बजाय एक और घातक राह बनता है।" }, [
    beat("ravana-sends-kharas-son", { en: "Ravana sends Khara's son", hi: "रावण खर के पुत्र को भेजता है" }, { en: "After Kumbha and Nikumbha die, Ravana turns to Makaraksha, son of Khara. The young commander's place in the battle is already tied to a father Rama killed in Dandaka. He leaves with confidence while the vehicle falters and dust rises, signs the fighters interpret as warnings without losing their ability to choose.", hi: "कुंभ और निकुंभ के मरने के बाद रावण खर के पुत्र मकराक्ष को भेजता है। युद्ध में युवा सेनानायक की जगह पहले ही उस पिता से जुड़ी है जिसे राम ने दंडक में मारा था। वह आत्मविश्वास से निकलता है, जबकि वाहन डगमगाता और धूल उठती है; योद्धा इन्हें चेतावनी मानते हैं, पर चुनाव की क्षमता नहीं खोते।" }, "Join Makaraksha's route to Khara's remembered death while leaving interpreted omens as influence rather than predetermined fate.", ["ravana", "makaraksha", "khara", "dandaka-memory", "war-chariot"]),
    beat("a-retreating-line-finds-rama", { en: "A retreating line finds Rama", hi: "पीछे हटती पंक्ति राम तक पहुँचती है" }, { en: "Makaraksha's arrows drive allied fighters backward until Rama covers their retreat and meets the advancing formation. Protection here is not a reward reserved for fearless behaviour; frightened people can move behind a stronger line without losing dignity. The confrontation then narrows toward the two people carrying the earlier Dandaka conflict.", hi: "मकराक्ष के बाण मित्र-योद्धाओं को पीछे धकेलते हैं, जब तक राम उनकी वापसी ढककर बढ़ते दल का सामना नहीं करते। यहाँ सुरक्षा केवल निर्भय व्यवहार का पुरस्कार नहीं; डरे लोग गरिमा खोए बिना मजबूत पंक्ति के पीछे जा सकते हैं। तब संघर्ष दंडक का पुराना भार लिए दो लोगों की ओर सिमटता है।" }, "Open a protected retreat corridor through Rama's position, then narrow attention toward Makaraksha without erasing the surrounding formations.", ["makaraksha", "rama", "allied-fighters", "lanka-defenders"]),
    beat("grief-speaks-through-dehumanising-threats", { en: "Grief speaks through dehumanising threats", hi: "शोक अमानवीय धमकियों में बोलता है" }, { en: "Makaraksha accuses Rama over Khara's death and promises revenge; Rama answers by recalling the larger Janasthana battle and threatening that scavengers will consume Makaraksha's body. Neither threat needs endorsement. They show how inherited grief and martial contempt strip the opponent of personhood before the actual exchange decides anything.", hi: "मकराक्ष खर की मृत्यु के लिए राम को दोष देकर प्रतिशोध का वचन देता है; राम जनस्थान का व्यापक युद्ध याद करके मकराक्ष के शरीर को मुर्दाखोरों द्वारा खाए जाने की धमकी देते हैं। किसी धमकी को समर्थन नहीं चाहिए। वे दिखाती हैं कि विरासत का शोक और युद्ध-अवमानना वास्तविक संघर्ष से पहले विरोधी की मनुष्यता छीनते हैं।" }, "Render the verbal threats as darkening relationship lines, not exciting pre-fight slogans, while Khara's absence remains present between them.", ["makaraksha", "rama", "khara", "dandaka-memory"]),
    beat("the-inherited-route-ends", { en: "The inherited route ends", hi: "विरासत की राह समाप्त होती है" }, { en: "Rama and Makaraksha break each other's arrows until Rama destroys the bow, chariot, driver, and horses. Makaraksha advances with a final empowered dart; Rama cuts it apart and kills him with a fire-linked arrow. The immediate threat ends, but a son following his father's death into the same conflict reveals how violence recruits the next relationship.", hi: "राम और मकराक्ष एक-दूसरे के बाण रोकते हैं, फिर राम धनुष, रथ, सारथि और घोड़े नष्ट करते हैं। मकराक्ष अंतिम समर्थ शक्ति लेकर बढ़ता है; राम उसे काटकर अग्नि-संबंधी बाण से मारते हैं। तत्काल खतरा मिटता है, पर पिता की मृत्यु के पीछे उसी संघर्ष में पहुँचा पुत्र दिखाता है कि हिंसा अगले संबंध को कैसे भर्ती करती है।" }, "End the revenge path at the ruined vehicle and final counter while keeping the father-son line as consequence, not destiny or glory.", ["makaraksha", "rama", "khara", "war-chariot", "battlefield"]),
  ]),
  scene("rama-refuses-collective-destruction", ["indrajit", "rama", "lakshmana", "allied-fighters", "lanka-defenders", "martial-altar", "hidden-chariot", "clouded-sky", "refuge-rules", "battlefield"], { en: "Rama rejects Lakshmana's proposal to destroy an entire people and defines protected conditions even inside war.", hi: "राम पूरे समाज को नष्ट करने का लक्ष्मण का प्रस्ताव ठुकराकर युद्ध के भीतर भी सुरक्षित स्थितियाँ तय करते हैं।" }, [
    beat("indrajit-prepares-concealment-again", { en: "Indrajit prepares concealment again", hi: "इंद्रजीत फिर अदृश्यता तैयार करता है" }, { en: "Ravana orders another hidden or visible attack after Makaraksha falls. Indrajit repeats the martial fire preparation, empowers a chariot, and leaves intending to clear the allies away for his father. Repetition matters: concealment is not an unlimited innate gift, but an advantage renewed through preparation, timing, and specific conditions.", hi: "मकराक्ष के गिरने पर रावण फिर छिपा या खुला आक्रमण करने को कहता है। इंद्रजीत युद्ध-अग्नि की तैयारी दोहराकर रथ समर्थ करता और पिता के लिए मित्र-दल मिटाने निकलता है। दोहराव महत्वपूर्ण है—अदृश्यता असीम जन्मजात शक्ति नहीं, तैयारी, समय और विशेष स्थितियों से फिर बनाई बढ़त है।" }, "Rebuild concealment through visible preparation steps so the advantage has conditions and can later be interrupted.", ["ravana", "indrajit", "martial-altar", "hidden-chariot"]),
    beat("arrows-arrive-from-cloud-and-smoke", { en: "Arrows arrive from cloud and smoke", hi: "बादल और धुएँ से बाण आते हैं" }, { en: "Cloud, smoke, silence, and height hide Indrajit's face, vehicle, bow, and movement while arrows strike the brothers and surrounding fighters. Rama and Lakshmana aim toward directions inferred from impact but cannot reliably touch him. The field again demonstrates how superior perception can defeat greater visible force without proving moral superiority.", hi: "बादल, धुआँ, मौन और ऊँचाई इंद्रजीत का चेहरा, वाहन, धनुष तथा गति छिपाते हैं, जबकि बाण भाइयों और आसपास के योद्धाओं को लगते हैं। राम-लक्ष्मण प्रहार की दिशा से अनुमान लगाकर बाण चलाते हैं, पर उसे विश्वसनीय रूप से छू नहीं पाते। मैदान फिर दिखाता है कि बेहतर दृष्टि बड़ी दृश्य शक्ति को हरा सकती है, नैतिक श्रेष्ठता सिद्ध किए बिना।" }, "Keep inferred firing cones uncertain and separate tactical visibility from any moral scoring of the people involved.", ["indrajit", "rama", "lakshmana", "allied-fighters", "clouded-sky"]),
    beat("lakshmana-proposes-an-entire-peoples-death", { en: "Lakshmana proposes an entire people's death", hi: "लक्ष्मण पूरे समाज की मृत्यु प्रस्तावित करते हैं" }, { en: "Hurt and unable to reach the hidden attacker, Lakshmana proposes using an overwhelming weapon against every Rakshasa. The impulse grows from immediate helplessness, but it would erase the distinction between Indrajit, active defenders, retreating fighters, captives, families, children, elders, and dissenters. Frustration cannot make collective identity a valid target.", hi: "घायल और छिपे आक्रमणकारी तक न पहुँच पाने पर लक्ष्मण हर राक्षस के विरुद्ध प्रचंड अस्त्र चलाने का प्रस्ताव रखते हैं। आवेग तत्काल असहायता से आता है, पर वह इंद्रजीत, सक्रिय रक्षक, पीछे हटते योद्धा, बंदी, परिवार, बच्चे, बुजुर्ग और असहमत लोगों का अंतर मिटा देगा। निराशा सामूहिक पहचान को वैध लक्ष्य नहीं बना सकती।" }, "Expand the proposed blast across visibly distinct military and civilian nodes, exposing the unacceptable collapse of categories before it occurs.", ["lakshmana", "indrajit", "lanka-defenders", "lanka-civilians", "rama"]),
    beat("rama-names-who-must-not-be-killed", { en: "Rama names who must not be killed", hi: "राम बताते हैं कि किन्हें नहीं मारा जाना चाहिए" }, { en: "Rama refuses punishment of all for one person's act. He says someone who has withdrawn, hidden from battle, fled, become bewildered, joined hands, sought shelter, or otherwise stopped posing the same threat must not be killed. The answer establishes restraint as active discrimination under pressure, then returns attention to finding Indrajit himself.", hi: "राम एक व्यक्ति के काम के लिए सबको दंड देने से इनकार करते हैं। वे कहते हैं कि जो युद्ध से हट गया, छिप गया, भागा, भ्रमित हुआ, हाथ जोड़कर खड़ा है, शरण माँगता है या अब वैसा खतरा नहीं रहा—उसे नहीं मारना चाहिए। उत्तर दबाव में सक्रिय भेद को संयम बनाता है, फिर ध्यान इंद्रजीत को खोजने पर लौटाता है।" }, "Turn each protected condition into a clear non-target state and narrow the pursuit back toward the responsible hidden attacker.", ["rama", "lakshmana", "indrajit", "refuge-rules", "lanka-defenders"]),
  ]),
  scene("false-sita-falls-before-hanuman", ["indrajit", "illusory-sita", "sita", "hanuman", "allied-fighters", "lanka-defenders", "aerial-fortress", "western-field", "nikumbhila", "missed-crag"], { en: "Indrajit weaponises an image of Sita's suffering, and Hanuman must act honestly while grief distorts the battlefield around him.", hi: "इंद्रजीत सीता की पीड़ा की छवि को हथियार बनाता है और शोक से बदले मैदान में हनुमान को ईमानदारी से कार्य करना पड़ता है।" }, [
    beat("a-familiar-captive-appears-on-the-chariot", { en: "A familiar captive appears on the chariot", hi: "रथ पर परिचित बंदी दिखाई देती हैं" }, { en: "Indrajit returns with an image matching the Sita Hanuman saw in the grove: soiled clothing, one braid, fasting, and visible distress. Because the details are accurate, Hanuman has strong reason to believe she is real. Deception succeeds by borrowing verified memory, not because the witness is foolish or careless.", hi: "इंद्रजीत ऐसी छवि लेकर लौटता है जो वाटिका में हनुमान द्वारा देखी सीता से मिलती है—मैला वस्त्र, एक वेणी, उपवास और स्पष्ट पीड़ा। विवरण सही होने से हनुमान के पास उसे वास्तविक मानने का मजबूत कारण है। छल प्रमाणित स्मृति उधार लेकर सफल होता है, गवाह की मूर्खता या लापरवाही से नहीं।" }, "Match the illusion to Hanuman's verified grove memory node by node, making his belief rational with the information available.", ["indrajit", "illusory-sita", "sita", "hanuman", "ashoka-grove-memory"]),
    beat("public-abuse-is-the-message", { en: "Public abuse is the message", hi: "सार्वजनिक प्रताड़ना ही संदेश है" }, { en: "Indrajit drags the image by her hair, ignores Hanuman's protest, and appears to kill her while declaring that enemy pain is reason enough. The display is coercive psychological violence aimed beyond the apparent victim at Hanuman, Rama, and the entire alliance. It should be shown through reaction, obstruction, and loss of control rather than lingering spectacle.", hi: "इंद्रजीत छवि को बालों से खींचता, हनुमान का विरोध अनसुना करता और यह कहते हुए मारता दिखता है कि शत्रु की पीड़ा ही पर्याप्त कारण है। प्रदर्शन दिखाई पड़ती पीड़ित से आगे हनुमान, राम और पूरे मित्र-दल पर लक्षित मानसिक हिंसा है। इसे ठहरते तमाशे के बजाय प्रतिक्रिया, अवरोध और नियंत्रण टूटने से दिखना चाहिए।" }, "Keep the apparent victim partly shielded by Hanuman's horrified viewpoint and focus on the coercive signal spreading through the watching ranks.", ["indrajit", "illusory-sita", "hanuman", "allied-fighters"]),
    beat("a-grief-driven-throw-misses", { en: "A grief-driven throw misses", hi: "शोक में फेंकी शिला लक्ष्य चूकती है" }, { en: "Hanuman rallies the fleeing group and hurls a huge crag at Indrajit's vehicle. The driver moves aside; the crag misses its intended target and crushes other defenders. Grief does not erase responsibility for a weapon's path. The failed strike makes collateral harm visible even while the person who threw it believed he was answering an atrocity.", hi: "हनुमान भागते दल को जुटाकर इंद्रजीत के वाहन पर विशाल शिला फेंकते हैं। सारथि हट जाता है; शिला लक्ष्य चूककर दूसरे रक्षकों को कुचलती है। शोक शस्त्र की राह की जिम्मेदारी नहीं मिटाता। चूका प्रहार तब भी अतिरिक्त हानि दिखाता है जब फेंकने वाला मानता है कि वह अत्याचार का उत्तर दे रहा है।" }, "Track the crag's intended and actual paths simultaneously, retaining the unintended casualties rather than hiding them after the miss.", ["hanuman", "indrajit", "lanka-defenders", "missed-crag"]),
    beat("hanuman-reports-what-he-believes", { en: "Hanuman reports what he believes", hi: "हनुमान वही बताते हैं जिसे सच मानते हैं" }, { en: "Hanuman decides that continuing the clash cannot restore the person he believes has died. He stops the allied attack and returns to tell Rama and Sugriva exactly what he witnessed, without inventing certainty beyond it. Meanwhile Indrajit uses the delay to begin the Nikumbhila preparation, revealing the deception's strategic purpose.", hi: "हनुमान तय करते हैं कि जारी संघर्ष उस व्यक्ति को नहीं लौटा सकता जिसे वे मरा मानते हैं। वे मित्र-आक्रमण रोककर राम और सुग्रीव को ठीक वही बताने लौटते हैं जो देखा, उससे अधिक निश्चितता नहीं गढ़ते। इस बीच इंद्रजीत देर का उपयोग निकुंभिला की तैयारी में करता है और छल का सैन्य उद्देश्य खुलता है।" }, "Split the route between an honest but mistaken report and Indrajit's hidden movement toward Nikumbhila, without blaming the witness.", ["hanuman", "rama", "sugriva", "indrajit", "nikumbhila"]),
  ]),
  scene("grief-argues-with-dharma", ["hanuman", "rama", "lakshmana", "sita", "jambavan", "allied-fighters", "dharma-question", "wealth-argument", "lanka", "grief-circle"], { en: "Apparent loss collapses Rama and drives Lakshmana into a furious argument whose contradictions belong to crisis, not settled guidance.", hi: "दिखाई पड़ी हानि राम को गिराती और लक्ष्मण को उग्र तर्क में ले जाती है, जिसके विरोधाभास संकट के हैं, स्थिर मार्गदर्शन के नहीं।" }, [
    beat("the-report-collapses-rama", { en: "The report collapses Rama", hi: "समाचार राम को गिरा देता है" }, { en: "Hanuman says that Indrajit killed Sita in front of the western force. Rama drops unconscious, and companions rush with water, touch, and support. No one has yet tested the report against other knowledge. The body's collapse arrives before analysis, showing how credible traumatic information can temporarily remove a leader's ability to decide.", hi: "हनुमान बताते हैं कि इंद्रजीत ने पश्चिमी दल के सामने सीता को मार दिया। राम अचेत गिरते हैं और साथी जल, स्पर्श तथा सहारे के साथ दौड़ते हैं। अभी किसी ने समाचार को दूसरी जानकारी से नहीं जाँचा। शरीर विश्लेषण से पहले गिरता है और दिखाता है कि विश्वसनीय आघात-सूचना नेता की निर्णय-क्षमता कुछ समय के लिए हटा सकती है।" }, "Collapse Rama's command controls and let care nodes take over before any tactical response or truth verification begins.", ["hanuman", "rama", "lakshmana", "allied-fighters", "grief-circle"]),
    beat("lakshmana-puts-virtue-on-trial", { en: "Lakshmana puts virtue on trial", hi: "लक्ष्मण धर्म को कटघरे में रखते हैं" }, { en: "Lakshmana argues that virtue seems powerless if Rama suffers while Ravana prospers. He questions whether unseen moral order exists and points to outcomes that appear reversed. The challenge is a serious voice from inside grief, not an error to erase; it also is not the final answer of the work or proof that ethical restraint has no value.", hi: "लक्ष्मण कहते हैं कि यदि राम दुख पाते और रावण फलता है तो धर्म शक्तिहीन लगता है। वे अदृश्य नैतिक व्यवस्था के अस्तित्व पर प्रश्न करके उलटे दिखते परिणामों की ओर संकेत करते हैं। चुनौती शोक के भीतर की गंभीर आवाज़ है, मिटाने योग्य गलती नहीं; पर वह कृति का अंतिम उत्तर या नैतिक संयम की निरर्थकता का प्रमाण भी नहीं।" }, "Place Lakshmana's challenge as an open unresolved branch beside prior acts of restraint, refusing both dismissal and automatic authority.", ["lakshmana", "rama", "ravana", "dharma-question"]),
    beat("wealth-and-force-become-griefs-shortcut", { en: "Wealth and force become grief's shortcut", hi: "धन और बल शोक का छोटा रास्ता बनते हैं" }, { en: "Lakshmana then claims wealth creates friendship, knowledge, power, and even access to virtue, blaming Rama's renunciation for present weakness. He urges strength before restraint. The argument compresses complex life into possession and force because grief demands a cause it can attack; it should not become advice that poverty diminishes a person's worth.", hi: "लक्ष्मण फिर कहते हैं कि धन मित्रता, ज्ञान, शक्ति और धर्म तक पहुँच बनाता है तथा वर्तमान कमजोरी के लिए राम के त्याग को दोष देते हैं। वे संयम से पहले बल चाहते हैं। तर्क जटिल जीवन को संपत्ति और शक्ति में सिमटाता है, क्योंकि शोक को प्रहार योग्य कारण चाहिए; इसे निर्धन व्यक्ति का मूल्य घटाने वाली सलाह नहीं बनना चाहिए।" }, "Show wealth and force as grief-driven explanatory shortcuts that narrow the world, while relationships formed without wealth remain visible.", ["lakshmana", "rama", "wealth-argument", "allied-fighters"]),
    beat("the-promise-to-raze-lanka-crosses-a-line", { en: "The promise to raze Lanka crosses a line", hi: "लंका मिटाने की प्रतिज्ञा सीमा पार करती है" }, { en: "Trying to make Rama rise, Lakshmana promises to remove the sorrow by levelling Lanka with its vehicles, animals, and leading defenders. The threat expands punishment from Indrajit and Ravana to a whole inhabited city. It is acute anger seeking action, not a humane plan; grief can explain the impulse without making civilian destruction acceptable.", hi: "राम को उठाने के लिए लक्ष्मण वाहनों, पशुओं और प्रमुख रक्षकों सहित लंका को समतल करके शोक हटाने का वचन देते हैं। धमकी दंड को इंद्रजीत और रावण से पूरे बसे नगर तक फैलाती है। यह काम खोजता तीव्र क्रोध है, मानवीय योजना नहीं; शोक आवेग समझा सकता है, नागरिक विनाश स्वीकार्य नहीं बनाता।" }, "Expand the threatened destruction across distinct civilian, animal, and military nodes, then hold it as an unexecuted crisis statement.", ["lakshmana", "lanka-civilians", "lanka-defenders", "city-animals", "rama"]),
  ]),
  scene("vibhishana-breaks-the-illusion", ["vibhishana", "rama", "lakshmana", "hanuman", "jambavan", "indrajit", "sita", "nikumbhila", "evidence-path", "allied-force"], { en: "Vibhishana tests the devastating report against intent and timing, reopening action without shaming the witnesses who believed it.", hi: "विभीषण विनाशकारी समाचार को मंशा और समय से जाँचकर उन गवाहों को लज्जित किए बिना कार्रवाई फिर खोलते हैं जिन्होंने उसे सच माना।" }, [
    beat("vibhishana-asks-what-happened", { en: "Vibhishana asks what happened", hi: "विभीषण पूछते हैं कि क्या हुआ" }, { en: "Vibhishana returns after placing forces and finds Rama on Lakshmana's lap, companions crying, and command suspended. He asks before correcting anyone. Lakshmana explains that Hanuman reported Sita's death. This short reconstruction preserves who saw what and prevents a confident alternative from appearing without an evidentiary path.", hi: "सेना व्यवस्थित करके लौटे विभीषण राम को लक्ष्मण की गोद में, साथियों को रोते और कमान को रुका पाते हैं। वे सुधारने से पहले पूछते हैं। लक्ष्मण बताते हैं कि हनुमान ने सीता की मृत्यु कही। यह छोटा पुनर्निर्माण तय रखता है कि किसने क्या देखा और किसी वैकल्पिक निष्कर्ष को प्रमाण-राह बिना अचानक आने से रोकता है।" }, "Reconstruct the report chain from Hanuman to Lakshmana to Rama before introducing Vibhishana's counter-explanation.", ["vibhishana", "hanuman", "lakshmana", "rama", "evidence-path"]),
    beat("intent-and-opportunity-do-not-fit", { en: "Intent and opportunity do not fit", hi: "मंशा और अवसर मेल नहीं खाते" }, { en: "Vibhishana says Ravana has repeatedly refused to release Sita because he intends to keep her, making a sudden order to kill her improbable. He also knows access to the guarded grove is tightly controlled. These facts do not prove safety alone, but they make the observed event require another explanation rather than immediate acceptance.", hi: "विभीषण कहते हैं कि रावण सीता को रखने की मंशा से बार-बार छोड़ने से इनकार कर चुका है, इसलिए अचानक उनकी हत्या का आदेश असंभावित है। वे यह भी जानते हैं कि पहरे वाली वाटिका तक पहुँच बहुत नियंत्रित है। ये तथ्य अकेले सुरक्षा सिद्ध नहीं करते, पर देखी घटना को तुरंत मानने के बजाय दूसरी व्याख्या माँगते हैं।" }, "Place Ravana's known intent and the grove's access controls against the apparent event as weighted evidence, not magical certainty.", ["vibhishana", "ravana", "sita", "ashoka-grove", "evidence-path"]),
    beat("the-delay-reveals-the-purpose", { en: "The delay reveals the purpose", hi: "देर उद्देश्य खोलती है" }, { en: "Vibhishana connects the spectacle to Indrajit's need for uninterrupted preparation at Nikumbhila. The false death explains why the western force withdrew and why the attacker disappeared instead of exploiting the apparent killing. Tactical timing turns the illusion from an inexplicable cruelty into a cruel method serving a concrete delay.", hi: "विभीषण दृश्य को निकुंभिला में इंद्रजीत की निर्बाध तैयारी की जरूरत से जोड़ते हैं। झूठी मृत्यु समझाती है कि पश्चिमी दल क्यों लौटा और आक्रमणकारी दिखाई पड़ी हत्या का लाभ उठाने के बजाय क्यों गायब हुआ। सैन्य समय भ्रम को अकारण क्रूरता से ठोस देर पैदा करने वाली क्रूर विधि में बदलता है।" }, "Connect withdrawal time directly to the Nikumbhila preparation meter, revealing motive without minimising the psychological harm.", ["vibhishana", "indrajit", "hanuman", "nikumbhila", "evidence-path"]),
    beat("a-time-limited-route-replaces-despair", { en: "A time-limited route replaces despair", hi: "सीमित समय की राह निराशा की जगह लेती है" }, { en: "Vibhishana explains that Indrajit becomes far harder to reach after completing the rite, while interruption leaves him exposed. Rama asks for the explanation again because grief has slowed comprehension, then sends Lakshmana with Hanuman, Jambavan, Vibhishana, and a substantial force. Composure returns through shared action, not by pretending the preceding pain was foolish.", hi: "विभीषण बताते हैं कि अनुष्ठान पूरा होने पर इंद्रजीत तक पहुँचना बहुत कठिन होगा, जबकि बाधा उसे खुला छोड़ती है। शोक से समझ धीमी होने पर राम व्याख्या फिर पूछते हैं, फिर लक्ष्मण को हनुमान, जाम्बवान, विभीषण और बड़े दल के साथ भेजते हैं। संयम साझा काम से लौटता है, पिछली पीड़ा को मूर्खता कहकर नहीं।" }, "Open a timed group route to Nikumbhila with repeated instructions available, preserving recovery from grief as a collective process.", ["rama", "lakshmana", "vibhishana", "hanuman", "jambavan", "allied-force", "nikumbhila"]),
  ]),
  scene("nikumbhila-opens-a-family-divide", ["indrajit", "vibhishana", "lakshmana", "hanuman", "jambavan", "allied-fighters", "lanka-defenders", "nikumbhila", "banyan-altar", "family-bond", "unfinished-rite"], { en: "The rite is interrupted, and the exposed battlefield becomes a family argument about whether kinship can demand service to continuing harm.", hi: "अनुष्ठान रुकता है और खुला युद्धक्षेत्र इस पारिवारिक प्रश्न में बदलता है कि क्या रक्त-संबंध जारी हानि की सेवा माँग सकता है।" }, [
    beat("the-protecting-ranks-must-be-crossed", { en: "The protecting ranks must be crossed", hi: "रक्षक पंक्तियाँ पार करनी होंगी" }, { en: "Vibhishana directs Lakshmana and the allied force into the dense formation protecting Nikumbhila. Bears, allied fighters, and Lanka's defenders collide under trees, arrows, rocks, and close weapons. The objective is interruption, but the route passes through many people whose own choices, loyalties, and survival cannot disappear behind the importance of the target.", hi: "विभीषण लक्ष्मण और मित्र-दल को निकुंभिला की रक्षा करती घनी पंक्ति में ले जाते हैं। भालू, मित्र-योद्धा और लंका-रक्षक वृक्ष, बाण, शिला और निकट शस्त्रों के बीच भिड़ते हैं। उद्देश्य बाधा डालना है, पर राह अनेक लोगों से गुजरती है जिनके चुनाव, निष्ठा और जीवन लक्ष्य के महत्व के पीछे गायब नहीं हो सकते।" }, "Show the objective beyond layered human obstacles, retaining individual retreat and injury paths rather than treating the formation as a wall.", ["lakshmana", "vibhishana", "allied-fighters", "lanka-defenders", "nikumbhila"]),
    beat("indrajit-leaves-the-rite-unfinished", { en: "Indrajit leaves the rite unfinished", hi: "इंद्रजीत अनुष्ठान अधूरा छोड़ता है" }, { en: "Hearing his protective force collapse, Indrajit rises before the offering is complete and enters his chariot. The intervention succeeds by changing conditions rather than overpowering an invincible completed state. Hanuman draws his attack, and Vibhishana points out the now-visible commander to Lakshmana.", hi: "रक्षक दल टूटता सुनकर इंद्रजीत अर्पण पूरा होने से पहले उठकर रथ पर चढ़ता है। हस्तक्षेप पूर्ण और अजेय स्थिति को हराने के बजाय परिस्थितियाँ बदलकर सफल होता है। हनुमान उसका प्रहार खींचते हैं और विभीषण अब दिखाई पड़ते सेनानायक को लक्ष्मण के लिए पहचानते हैं।" }, "Freeze the completion path at an unfinished state and reveal Indrajit's fixed position as Hanuman and Vibhishana coordinate attention.", ["indrajit", "unfinished-rite", "hanuman", "vibhishana", "lakshmana"]),
    beat("indrajit-calls-departure-betrayal", { en: "Indrajit calls departure betrayal", hi: "इंद्रजीत अलग होने को विश्वासघात कहता है" }, { en: "Indrajit turns on his uncle and argues that birth, kinship, and shared people should outweigh every defect within one's own side. He predicts that outsiders will discard a defector after using him. The accusation carries real pain and a legitimate fear about belonging, even as it demands loyalty regardless of abduction, rejected counsel, and continuing harm.", hi: "इंद्रजीत चाचा से कहता है कि जन्म, रक्त-संबंध और साझा समाज अपने पक्ष के हर दोष से ऊपर होने चाहिए। वह चेताता है कि बाहरी लोग उपयोग के बाद अलग हुए व्यक्ति को छोड़ देंगे। आरोप में वास्तविक पीड़ा और अपनापन खोने का उचित डर है, फिर भी वह अपहरण, ठुकराई सलाह और जारी हानि के बावजूद निष्ठा माँगता है।" }, "Keep the family bond warm and wounded while showing the specific harms it is being asked to override, avoiding a simple traitor label.", ["indrajit", "vibhishana", "family-bond", "ravana", "sita"]),
    beat("vibhishana-names-why-he-left", { en: "Vibhishana names why he left", hi: "विभीषण बताते हैं कि वे क्यों अलग हुए" }, { en: "Vibhishana answers that kinship does not require participation in theft, violation, fear among friends, attacks on sages, pride, anger, endless hostility, and contempt for counsel. He admits tears at the prospect of his nephew's death and leaves the killing to Lakshmana. Moral separation here costs belonging and affection; it is not effortless purity.", hi: "विभीषण उत्तर देते हैं कि रक्त-संबंध चोरी, उल्लंघन, मित्रों में भय, ऋषियों पर आक्रमण, गर्व, क्रोध, अंतहीन शत्रुता और सलाह के अपमान में भागीदारी नहीं माँगता। वे भतीजे की मृत्यु की संभावना पर आँसू स्वीकारते और अंतिम प्रहार लक्ष्मण पर छोड़ते हैं। नैतिक अलगाव अपनापन और स्नेह की कीमत लेता है; वह सहज पवित्रता नहीं।" }, "Show Vibhishana's boundary as costly severance with tears and retained kinship, while transferring the direct duel to Lakshmana.", ["vibhishana", "indrajit", "lakshmana", "family-bond", "sita"]),
  ]),
  scene("the-duel-wears-both-warriors-down", ["lakshmana", "indrajit", "hanuman", "vibhishana", "allied-fighters", "lanka-defenders", "war-chariot", "broken-armour", "nikumbhila", "support-lines"], { en: "The long duel strips armour, certainty, and strength from both fighters while support remains essential around them.", hi: "लंबा द्वंद्व दोनों योद्धाओं से कवच, निश्चितता और शक्ति छीनता है, जबकि आसपास सहारा अनिवार्य रहता है।" }, [
    beat("each-man-rejects-the-others-claim-to-honour", { en: "Each man rejects the other's claim to honour", hi: "दोनों एक-दूसरे के सम्मान-दावे को ठुकराते हैं" }, { en: "Indrajit recalls his earlier hidden victories and promises Lakshmana's death; Lakshmana calls concealment a thief's method and demands open action. Their insults reveal competing martial ideals, but neither ideal alone decides right conduct. Open combat can still serve Ravana's wrongful refusal, and hidden tactics can still be judged by their targets and effects rather than ancestry.", hi: "इंद्रजीत पिछली छिपी जीत याद करके लक्ष्मण की मृत्यु का वचन देता है; लक्ष्मण अदृश्यता को चोर की विधि कहकर खुली कार्रवाई माँगते हैं। उनके अपमान प्रतिस्पर्धी युद्ध-आदर्श खोलते हैं, पर कोई आदर्श अकेला सही आचरण तय नहीं करता। खुला युद्ध रावण के गलत इनकार की सेवा कर सकता है और छिपी नीति का निर्णय वंश से नहीं, लक्ष्य तथा परिणाम से होना चाहिए।" }, "Place the two honour codes beside the actual causal and harm paths, preventing style of combat from becoming automatic morality.", ["lakshmana", "indrajit", "vibhishana", "nikumbhila"]),
    beat("armour-and-blood-record-time", { en: "Armour and blood record time", hi: "कवच और रक्त समय दर्ज करते हैं" }, { en: "Arrows pierce Lakshmana, Indrajit, Hanuman, and Vibhishana. Both main fighters lose armour and continue for a long time with blood, damaged equipment, and repeated effort accumulating rather than resetting. The inherited praise of beauty in wounded bodies should not turn injury into decoration; changing posture and slower response show the cost more honestly.", hi: "बाण लक्ष्मण, इंद्रजीत, हनुमान और विभीषण को घायल करते हैं। दोनों मुख्य योद्धा कवच खोते और लंबे समय तक रक्त, टूटे साधन तथा जुड़ती मेहनत के साथ चलते हैं, हर चरण में नए नहीं होते। घायल शरीर की पुरानी सौंदर्य-प्रशंसा चोट को सजावट न बनाए; बदलती मुद्रा और धीमा उत्तर कीमत अधिक ईमानदारी से दिखाते हैं।" }, "Accumulate damaged armour, slower movement, and support needs without beautifying blood or refreshing stamina between exchanges.", ["lakshmana", "indrajit", "hanuman", "vibhishana", "broken-armour"]),
    beat("the-duel-is-not-only-two-people", { en: "The duel is not only two people", hi: "द्वंद्व केवल दो लोगों का नहीं" }, { en: "Lanka's defenders and the allied force continue fighting around the central exchange. Hanuman carries Lakshmana, Vibhishana identifies signs and threats, and other people absorb weapons aimed toward the principals. Calling the event a duel is useful for orientation, but its survival depends on many bodies, decisions, and relief efforts outside the two names.", hi: "लंका-रक्षक और मित्र-दल केंद्रीय संघर्ष के आसपास लड़ते रहते हैं। हनुमान लक्ष्मण को उठाते, विभीषण संकेत तथा खतरे पहचानते और दूसरे लोग मुख्य योद्धाओं की ओर आए शस्त्र झेलते हैं। घटना को द्वंद्व कहना दिशा देता है, पर उसका टिकना दो नामों से बाहर अनेक शरीरों, निर्णयों और राहत-प्रयासों पर निर्भर है।" }, "Keep support, shielding, identification, and surrounding combat lines active around the two focal figures instead of freezing the world.", ["lakshmana", "indrajit", "hanuman", "vibhishana", "allied-fighters", "lanka-defenders"]),
    beat("vibhishana-steps-in-with-grief", { en: "Vibhishana steps in with grief", hi: "विभीषण शोक के साथ आगे आते हैं" }, { en: "When the long exchange exhausts Lakshmana, Vibhishana moves forward to relieve pressure even though Indrajit is his nephew. He reads the opponent's weakening signs while admitting the emotional conflict elsewhere. Assistance is not detached tactical expertise; it asks him to help create the death of someone he still recognises as family.", hi: "लंबा संघर्ष लक्ष्मण को थकाता है तो विभीषण दबाव बाँटने आगे आते हैं, यद्यपि इंद्रजीत उनका भतीजा है। वे विरोधी की कमजोरी के संकेत पढ़ते हैं और दूसरे स्थान पर भावनात्मक संघर्ष स्वीकार चुके हैं। सहायता निर्लिप्त सैन्य कौशल नहीं; वह उनसे उस व्यक्ति की मृत्यु बनाने में मदद माँगती है जिसे वे अब भी परिवार मानते हैं।" }, "Overlay Vibhishana's support path with the unresolved family bond, so tactical help visibly carries grief rather than erasing it.", ["vibhishana", "lakshmana", "indrajit", "family-bond", "support-lines"]),
  ]),
  scene("indrajit-falls-and-the-wounded-return", ["lakshmana", "indrajit", "vibhishana", "hanuman", "jambavan", "rama", "sushena", "allied-fighters", "lanka-defenders", "first-chariot", "second-chariot", "care-circle", "nikumbhila"], { en: "Indrajit returns after losing one chariot and finally falls; Lakshmana's supported return ends in care rather than invulnerable celebration.", hi: "एक रथ खोकर लौटे इंद्रजीत का अंत होता है; लक्ष्मण की सहारे वाली वापसी अजेय उत्सव नहीं, देखभाल में समाप्त होती है।" }, [
    beat("the-first-chariot-is-dismantled", { en: "The first chariot is dismantled", hi: "पहला रथ टूटता है" }, { en: "Lakshmana kills the charioteer, allied leaders bring down the horses, and Indrajit must fight on foot while trying to manage several tasks at once. Vehicle loss changes visibility, mobility, and protection but does not end his capacity. The animals and driver are part of the cost that makes the tactical opening possible.", hi: "लक्ष्मण सारथि को मारते, मित्र-नेता घोड़े गिराते और इंद्रजीत कई काम एक साथ संभालते हुए पैदल लड़ने को मजबूर होता है। वाहन की हानि दृश्यता, गति और सुरक्षा बदलती है, पर उसकी क्षमता समाप्त नहीं करती। पशु और सारथि उस कीमत का हिस्सा हैं जिससे सैन्य अवसर बनता है।" }, "Dismantle mobility through driver and horse losses while retaining those lives as consequences, not disposable vehicle components.", ["lakshmana", "indrajit", "allied-fighters", "first-chariot", "charioteer", "chariot-horses"]),
    beat("darkness-allows-a-return", { en: "Darkness allows a return", hi: "अँधेरा वापसी का अवसर देता है" }, { en: "Indrajit tells his defenders to exploit darkness while he slips into Lanka for a replacement chariot. They must hold the field without knowing every friend from opponent. He returns quickly with a new driver, horses, weapons, and renewed mobility, showing why destruction of equipment was a temporary advantage rather than a completed victory.", hi: "इंद्रजीत रक्षकों से अँधेरे का लाभ लेकर मैदान थामने को कहता है और दूसरे रथ के लिए लंका जाता है। उन्हें हर मित्र और विरोधी की पहचान बिना लड़ना है। वह नए सारथि, घोड़े, शस्त्र और गति के साथ शीघ्र लौटता है; इसलिए साधन-विनाश पूर्ण जीत नहीं, अस्थायी बढ़त था।" }, "Keep the defenders' uncertain holding pattern visible while a replacement-equipment route connects the battlefield to Lanka and back.", ["indrajit", "lanka-defenders", "second-chariot", "lanka", "nikumbhila"]),
    beat("the-final-weapon-ends-a-human-life", { en: "The final weapon ends a human life", hi: "अंतिम अस्त्र एक जीवन समाप्त करता है" }, { en: "After more exchanges and cancelled weapons, Lakshmana invokes a final arrow through Rama's truthfulness and prowess and kills Indrajit. Defenders flee toward city, sea, and mountains while allied ranks celebrate relief from a formidable attacker. The death ends a tactical threat and a son's life at once; celestial praise cannot erase the family's grief that will follow.", hi: "और संघर्ष तथा एक-दूसरे को रोकते अस्त्रों के बाद लक्ष्मण राम की सत्यनिष्ठा तथा पराक्रम का स्मरण करके अंतिम बाण चलाते और इंद्रजीत को मारते हैं। रक्षक नगर, समुद्र और पर्वतों की ओर भागते हैं, जबकि मित्र-दल प्रबल आक्रमणकारी से राहत मनाता है। मृत्यु सैन्य खतरा और पुत्र का जीवन साथ समाप्त करती है; दिव्य प्रशंसा आगे आने वाला पारिवारिक शोक नहीं मिटाती।" }, "Show tactical relief and the severed father-son connection simultaneously, with clear safe flight routes for disarmed defenders.", ["lakshmana", "indrajit", "ravana", "lanka-defenders", "allied-fighters"]),
    beat("lakshmana-returns-needing-care", { en: "Lakshmana returns needing care", hi: "लक्ष्मण उपचार की जरूरत के साथ लौटते हैं" }, { en: "Lakshmana cannot simply walk back as an untouched victor; he leans on Vibhishana and Hanuman. Rama embraces him, notices wounds, and asks Sushena to treat Lakshmana and every reachable injured companion. Recovery is shared across leaders and unnamed fighters, making care the final movement of the arc rather than the winner's pose.", hi: "लक्ष्मण अछूते विजेता की तरह अकेले नहीं लौट सकते; वे विभीषण और हनुमान पर टिकते हैं। राम उन्हें गले लगाकर घाव देखते और सुषेण से लक्ष्मण तथा पहुँच सकने वाले हर घायल साथी का उपचार करने को कहते हैं। स्वस्थ होना नेताओं और अनाम योद्धाओं में साझा है, इसलिए अंतिम गति विजेता की मुद्रा नहीं, देखभाल है।" }, "Move from supported return into one expanding care circle that includes Lakshmana, Vibhishana, Hanuman, and unnamed wounded allies.", ["lakshmana", "vibhishana", "hanuman", "rama", "sushena", "allied-fighters", "care-circle"]),
  ]),
];
